def receiver_members():
    owner = ticket(42)
    check(owner.serial == owner.get().serial == 42)
    check(owner.label == owner.get().label == "owner\0🙂")
    check(isinstance(api.Value.serial, property) and api.Value.serial.fget(owner) == 42)
    unbound = api.Value.retain_ticket(owner)
    check(unbound.serial == 42 and "retain_ticket" in dir(owner))
    view = owner.retain_ticket()
    child, kept = view.retain_ticket(), view.retain()
    copied = owner.label
    owner.close()
    check("retain_ticket" in dir(owner))
    check(view.is_closed and child.is_closed and unbound.is_closed and copied == "owner\0🙂")
    rejected(r.LeanBridgeError, lambda: view.serial, 4)
    check(kept.serial == 42)
    for argument in (kept, kept.get()):
        chosen_owner = ticket(81)
        chosen = argument.choose_ticket(chosen_owner)
        check(chosen.serial == 81)
        chosen_owner.close()
        check(chosen.is_closed and kept.serial == 42)
    receiver, source = ticket(1), ticket(2)
    selected = receiver.choose_ticket(source)
    receiver.close()
    check(selected.serial == 2)
    source.close()
    check(selected.is_closed)
    rejected(TypeError, lambda: kept.choose_ticket(kept.get()))
    rejected(AttributeError, lambda: kept.get().retain_ticket)
    record = api.copy_value(sample())
    check(record.payload == data() and record.primary.serial == 7)
    check(record.get().primary.serial == 7)
    rejected(AttributeError, lambda: record.serial)
    record_view = record.echo_record()
    callback_view = record.callback_record(lambda incoming: incoming)
    closure = record.make_record()
    closure_view = closure(False, sample())
    check(closure_view.get().primary.serial == 7)
    record.close()
    check(record_view.is_closed and callback_view.is_closed and closure.is_closed)
    check(not closure_view.is_closed and closure_view.get().primary.serial == 7)
    closure_view.close()
    for branch in (api.ChoiceEmpty(), api.ChoiceMany(()), api.ChoiceOne(kept.get())):
        choice = api.copy_value(branch)
        borrowed = choice.echo_variant()
        check(borrowed.get() == branch)
        choice.close()
        check(borrowed.is_closed)
    for branch in (api.TreeBranch(()), api.TreeLeaf(kept.get())):
        tree = api.copy_value(branch)
        borrowed = tree.echo_recursive()
        callback = tree.callback_recursive(lambda incoming: incoming)
        closure = tree.make_recursive()
        output = closure(False, branch)
        check(output.get() == borrowed.get() == callback.get() == branch)
        tree.close()
        check(borrowed.is_closed and callback.is_closed and closure.is_closed)
        check(not output.is_closed and output.get() == branch)
        output.close()
    root = ticket(12)
    alias, dependent = copy.copy(root), root.retain_ticket()
    moved = root.transfer_ticket()
    check(root.is_closed and alias.is_closed and dependent.is_closed and moved.serial == 12)
    record = api.copy_value(sample())
    alias, dependent = copy.copy(record), record.echo_record()
    escaped = []
    def during(incoming):
        check(record.is_closed and alias.is_closed and dependent.is_closed)
        check(incoming.primary.serial == 7)
        escaped.append(incoming.primary)
        return incoming
    moved_record = record.move_record(during)
    check(moved_record.primary.serial == 7)
    rejected(r.LeanBridgeError, lambda: escaped[0].serial, 4)
    root, other = ticket(6), ticket(9)
    mixed = root.mixed_ticket(other)
    check(not root.is_closed and other.is_closed and mixed.serial == 9)
    root.close()
    check(mixed.is_closed)
    # Bound methods recheck the original owner when invoked later.
    owner = ticket(77)
    later = owner.retain_ticket
    owner.close()
    rejected(r.LeanBridgeError, later, 4)
